(() => {
'use strict';
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d',{alpha:false}),shell=document.querySelector('#shell');
const $=s=>document.querySelector(s), screen=$('#screen'), content=$('.screen-content');
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a),pick=a=>a[Math.floor(Math.random()*a.length)];
let W=640,H=360, last=0, state='menu',audioCtx=null,musicOn=true,sfxOn=true,shake=0,gameTime=0,spawnTimer=0,toastTimer=0;
const save=JSON.parse(localStorage.getItem('neonrun-save')||'{}');
const meta={high:save.high||0,totalKills:save.totalKills||0,bestWave:save.bestWave||0,runs:save.runs||0,unlocks:save.unlocks||[]};
const keys=new Set(), touch={x:0,y:0,attack:false,special:false};
const player={x:0,y:0,r:9,hp:100,maxHp:100,speed:138,damage:24,fireRate:.24,attackTimer:0,invuln:0,armor:0,crit:0,shield:0,dash:0,dashCd:0,slowTime:0,berserk:0,weapon:'MONOWIRE',kills:0};
let wave=1,score=0,credits=0,kills=0,enemies=[],bullets=[],enemyShots=[],particles=[],implants=[],boss=null,stats={damage:0,shots:0,abilities:0},screenReturn='menu';
const implantList=[
{id:'reinforced',name:'Reinforced Sinew',rarity:'COMMON / BODY',cost:75,desc:'+30 max health and restore 30 VITALS.',apply:()=>{player.maxHp+=30;player.hp=Math.min(player.maxHp,player.hp+30)}},
{id:'mono',name:'Mono Edge',rarity:'COMMON / WEAPON',cost:90,desc:'Strike damage +35%. Clean cuts pay +2¢.',apply:()=>{player.damage*=1.35}},
{id:'reflex',name:'Kerenzikov Reflex',rarity:'RARE / NERVOUS',cost:120,desc:'Attack cadence +25%, move speed +8%.',apply:()=>{player.fireRate*=.75;player.speed*=1.08}},
{id:'plating',name:'Subdermal Plating',rarity:'COMMON / SKIN',cost:100,desc:'Armor reduces incoming damage by 2.',apply:()=>{player.armor+=2}},
{id:'optics',name:'Threat Optics',rarity:'RARE / OCULAR',cost:130,desc:'Critical strikes +18% chance for 2× damage.',apply:()=>{player.crit+=.18}},
{id:'tendon',name:'Hydraulic Tendons',rarity:'COMMON / LEGS',cost:85,desc:'Move 18% faster. Dash recharge -20%.',apply:()=>{player.speed*=1.18;player.dashCd*=.8}},
{id:'shield',name:'Aegis Nanoshield',rarity:'EPIC / CORE',cost:190,desc:'Absorb one hit every 9 seconds.',apply:()=>{player.shield=Math.max(player.shield,9)}},
{id:'dash',name:'Reflex Booster',rarity:'RARE / LEGS',cost:145,desc:'Cyber dash cooldown -35%. Dash hurts enemies.',apply:()=>{player.dashCd*=.65;player.dash+=1}},
{id:'vamp',name:'Bloodware Leech',rarity:'EPIC / CORE',cost:210,desc:'Restore 2 health per takedown.',apply:()=>{player.vamp=true}},
{id:'overclock',name:'Overclocked Synapse',rarity:'LEGENDARY / NERVOUS',cost:260,desc:'Attack speed +35%. Crits also recharge cyber.',apply:()=>{player.fireRate*=.65;player.overclock=true}},
{id:'reactor',name:'Microfusion Cell',rarity:'EPIC / CORE',cost:200,desc:'Cyber ability recharges 30% faster.',apply:()=>{player.coolMult=(player.coolMult||1)*.7}},
{id:'shock',name:'Arc Discharge',rarity:'LEGENDARY / WEAPON',cost:280,desc:'Every 4th strike chains lightning to nearby foes.',apply:()=>{player.arc=true}}
];
const types={officer:{name:'OFFICER',hp:30,speed:38,damage:8,color:'#ff4f79',r:8,ai:'chase',value:10},armor:{name:'ARMORED',hp:92,speed:22,damage:15,color:'#fb9c4a',r:11,ai:'chase',value:22},sniper:{name:'SNIPER',hp:36,speed:25,damage:15,color:'#e9da75',r:8,ai:'snipe',value:18},tactical:{name:'TACTICAL',hp:46,speed:34,damage:10,color:'#72a9ff',r:9,ai:'flank',value:16},hunter:{name:'CYBER HUNTER',hp:66,speed:53,damage:13,color:'#d866ff',r:10,ai:'dash',value:25},elite:{name:'ELITE',hp:75,speed:40,damage:14,color:'#ff3559',r:10,ai:'smart',value:28}};
const abilities=[{id:'sandevistan',name:'SANDEVISTAN',desc:'Slow time for 4 seconds. Your reflexes stay fast.',cool:12},{id:'smash',name:'GROUND SMASH',desc:'Shockwave deals heavy damage in a wide radius.',cool:9},{id:'emp',name:'EMP BURST',desc:'Stun and damage all nearby cyberware.',cool:11},{id:'berserk',name:'BERSERK MODE',desc:'Double damage and shrug off pain for 5 seconds.',cool:14}];
let abilityIndex=0,abilityCd=0;
function persist(){localStorage.setItem('neonrun-save',JSON.stringify(meta))}
function resize(){const r=shell.getBoundingClientRect();const aspect=r.width/r.height;W=640;H=640/aspect;canvas.width=Math.round(W);canvas.height=Math.round(H)}
new ResizeObserver(resize).observe(shell);resize();
function audio(freq=220,dur=.08,type='square',vol=.025){if(!sfxOn)return;try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(vol,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+dur);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+dur)}catch(e){}}
function music(){if(!musicOn)return;audio(55,.35,'sawtooth',.012);setTimeout(()=>{if(musicOn&&state==='playing')audio(pick([110,146,164,220]),.17,'triangle',.012)},200)}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1700)}
function show(html){screen.classList.remove('hidden');content.innerHTML=html;}
function hide(){screen.classList.add('hidden')}
function updateHud(){ $('#health-fill').style.width=`${100*player.hp/player.maxHp}%`;$('#health-text').textContent=`${Math.ceil(player.hp)}/${player.maxHp}`;$('#wave').textContent=String(wave).padStart(2,'0');$('#score').textContent=String(score).padStart(6,'0');$('#credits').textContent=credits;$('#enemies').textContent=enemies.length+(boss?1:0); }
function startGame(){player.x=player.y=0;player.hp=player.maxHp=100;player.speed=138;player.damage=24;player.fireRate=.24;player.armor=player.crit=player.dash=0;player.shield=0;player.weapon='MONOWIRE';player.kills=0;player.vamp=player.arc=player.overclock=false;player.coolMult=1;wave=1;score=credits=kills=0;enemies=[];bullets=[];enemyShots=[];particles=[];implants=[];boss=null;stats={damage:0,shots:0,abilities:0};abilityCd=0;abilityIndex=0;player.dashCd=0;player.invuln=0;state='playing';meta.runs++;persist();$('#hud').classList.remove('hidden');$('#combat-hint').classList.remove('hidden');$('#touch-controls').classList.remove('hidden');hide();beginWave();audio(120,.2,'sawtooth');}
function menu(){state='menu';$('#hud').classList.add('hidden');$('#combat-hint').classList.add('hidden');$('#touch-controls').classList.add('hidden');show(`<div class="menu-layout"><div><div class="eyebrow">NIGHT CITY • FUGITIVE PROTOCOL</div><h1 class="title">NEON<br><em>//</em>RUN</h1><div class="subtitle">THE CITY DOESN'T FORGIVE. NEITHER DO YOU.</div><p class="intro">You were built to serve the system. Now every badge in the city wants you erased. Survive the hunt. Upgrade your chrome. Become the glitch they can't contain.</p><div class="menu-actions"><button class="btn" id="start">▶ &nbsp; JACK IN</button><button class="btn secondary" id="stats-open">RECORDS</button><button class="btn secondary" id="settings-open">SETTINGS</button></div><p class="screen-lede" style="margin-top:18px">BEST RUN &nbsp;<b style="color:var(--gold)">${meta.high.toLocaleString()}</b> &nbsp; / &nbsp; WAVE ${meta.bestWave}</p></div><aside class="menu-side"><h3>✦ &nbsp; WANTED: ALIVE / DEAD</h3><p>WAVE ${String(wave).padStart(2,'0')} • ${Math.max(3,3+Math.floor(wave*1.35))} HOSTILES DETECTED</p><p>MOVE <span style="color:var(--cyan)">WASD / STICK</span><br>STRIKE <span style="color:var(--cyan)">SPACE / ATTACK</span><br>CYBER <span style="color:var(--cyan)">Q / SPECIAL</span><br>PAUSE <span style="color:var(--cyan)">ESC</span></p><p style="color:#ff5480">⚠ WANTED LEVEL RISES EVERY WAVE<br>⚠ ELITE TARGET EVERY 10 WAVES</p></aside></div>`);$('#start').onclick=startGame;$('#stats-open').onclick=showStats;$('#settings-open').onclick=showSettings;}
function showStats(){state='menu';show(`<div class="eyebrow">AFTER-ACTION INTELLIGENCE</div><h2 class="screen-heading">RUN RECORDS</h2><p class="screen-lede">Every run leaves a mark. Your legend is saved on this device.</p><div class="stats-grid"><div class="stat-card"><b>${meta.high.toLocaleString()}</b><span>BEST SCORE</span></div><div class="stat-card"><b>${meta.bestWave}</b><span>DEEPEST WAVE</span></div><div class="stat-card"><b>${meta.totalKills}</b><span>TOTAL TAKEDOWNS</span></div><div class="stat-card"><b>${meta.runs}</b><span>RUNS ATTEMPTED</span></div><div class="stat-card"><b>${implants.length}</b><span>CHROME THIS RUN</span></div><div class="stat-card"><b>${meta.unlocks.length}</b><span>ARCHIVED BADGES</span></div></div><button class="btn secondary" id="back">← BACK</button>`);$('#back').onclick=menu;}
function showSettings(){state='menu';show(`<div class="eyebrow">SYSTEM CONFIGURATION</div><h2 class="screen-heading">SETTINGS</h2><p class="screen-lede">Tune the signal. Settings are saved for this session.</p><div class="settings-row"><span>Synthwave soundtrack</span><button class="toggle" id="music">${musicOn?'ON':'OFF'}</button></div><div class="settings-row"><span>Combat sound effects</span><button class="toggle" id="sfx">${sfxOn?'ON':'OFF'}</button></div><div class="settings-row"><span>Control scheme</span><span style="color:var(--cyan);font:10px 'Share Tech Mono'">KEYBOARD + TOUCH</span></div><div class="menu-actions"><button class="btn secondary" id="back">← BACK</button><button class="btn danger" id="reset">RESET RECORDS</button></div>`);$('#music').onclick=e=>{musicOn=!musicOn;e.target.textContent=musicOn?'ON':'OFF'};$('#sfx').onclick=e=>{sfxOn=!sfxOn;e.target.textContent=sfxOn?'ON':'OFF'};$('#back').onclick=menu;$('#reset').onclick=()=>{if(confirm('Erase all local records?')){Object.assign(meta,{high:0,bestWave:0,totalKills:0,runs:0,unlocks:[]});persist();menu()}};}

