$('#reset').onclick=()=>{if(confirm('Erase all local records?')){Object.assign(meta,{high:0,bestWave:0,totalKills:0,runs:0,unlocks:[]});persist();menu()}};}
function beginWave(){state='playing';spawnTimer=.45;let count=Math.min(5+wave*2,36);if(wave%10===0){boss={x:rand(-W*.42,W*.42),y:-H*.48,hp:500+wave*65,maxHp:500+wave*65,r:23,phase:1,attack:1.2,hit:0,name:pick(['THE WARDEN','CHROME REAPER','MAX-TAC PRIME'])};toast(`⚠ BOSS SIGNATURE DETECTED — ${boss.name}`);count=Math.max(4,Math.floor(count*.62))}enemies.waveLeft=count;enemies.spawned=0;updateHud()}
function spawnEnemy(){let angle=rand(0,Math.PI*2),dist=Math.max(W,H)*.56, x=player.x+Math.cos(angle)*dist,y=player.y+Math.sin(angle)*dist;let pool=['officer','officer','officer'];if(wave>=2)pool.push('armor');if(wave>=3)pool.push('sniper','tactical');if(wave>=5)pool.push('hunter');if(wave>=7)pool.push('elite');let type=pick(pool),base=types[type],scale=1+(wave-1)*.12;enemies.push({x,y,hp:base.hp*scale,maxHp:base.hp*scale,speed:base.speed*(1+wave*.018),damage:base.damage*(1+wave*.045),color:base.color,r:base.r,ai:base.ai,value:base.value,type,attack:rand(.4,1.8),stun:0,angle:0,phase:0});enemies.spawned++}
function showShop(){state='shop';$('#combat-hint').classList.add('hidden');$('#touch-controls').classList.add('hidden');let picks=implantList.slice().sort(()=>Math.random()-.5).slice(0,9);show(`<div class="eyebrow">WAVE ${String(wave).padStart(2,'0')} CLEARED • ${Math.round(credits)}¢ AVAILABLE</div><h2 class="screen-heading">BLACK MARKET</h2><p class="screen-lede">BUY AS MANY IMPLANTS AS YOU CAN AFFORD. Chrome is forever.</p><div class="shop-grid">${picks.map(it=>`<article class="implant" data-id="${it.id}"><span class="rarity">${it.rarity}</span>${implants.includes(it.id)?'<span class="tag">INSTALLED</span>':''}<h3>${it.name}</h3><p>${it.desc}</p><div class="price">¢ ${it.cost}</div></article>`).join('')}</div><div class="shop-footer"><span class="wallet">WALLET &nbsp; ¢ <b id="wallet">${credits}</b></span><div class="menu-actions" style="margin:0"><button class="btn secondary" id="heal">PATCH UP &nbsp; ¢ 35</button><button class="btn" id="next">${wave%10===9?'FACE THE BOSS':'NEXT WAVE'} →</button></div></div><p class="screen-lede" style="margin-top:11px">${implants.length?`ACTIVE CHROME: ${implants.map(id=>implantList.find(i=>i.id===id)?.name).filter(Boolean).join(' • ')}`:'NO IMPLANTS INSTALLED'}</p>`);
content.querySelectorAll('.implant').forEach(card=>card.onclick=()=>{let it=implantList.find(i=>i.id===card.dataset.id);if(implants.includes(it.id)){toast('IMPLANT ALREADY INSTALLED');return}if(credits<it.cost){toast('INSUFFICIENT CREDITS');return}credits-=it.cost;it.apply();implants.push(it.id);audio(640,.12,'triangle');showShop()});$('#heal').onclick=()=>{if(credits<35){toast('INSUFFICIENT CREDITS');return}if(player.hp>=player.maxHp){toast('VITALS ALREADY OPTIMAL');return}credits-=35;player.hp=Math.min(player.maxHp,player.hp+45);showShop()};$('#next').onclick=()=>{hide();$('#touch-controls').classList.remove('hidden');$('#combat-hint').classList.remove('hidden');wave++;beginWave()};}
function completeWave(){if(state!=='playing')return;state='shop';let bonus=20+wave*5;credits+=bonus;score+=wave*100;toast(`SECTOR CLEARED • +${bonus}¢`);audio(520,.2,'triangle');updateHud();setTimeout(()=>{if(state==='shop')showShop()},450)}
function gameOver(){if(state==='over')return;state='over';$('#touch-controls').classList.add('hidden');$('#combat-hint').classList.add('hidden');$('#hud').classList.add('hidden');meta.totalKills+=kills;meta.high=Math.max(meta.high,score);meta.bestWave=Math.max(meta.bestWave,wave);if(kills>=10&&!meta.unlocks.includes('street'))meta.unlocks.push('street');persist();show(`<div class="eyebrow" style="color:var(--pink)">SIGNAL LOST • MAX-TAC CLAIMS THE BLOCK</div><h2 class="screen-heading" style="font-size:clamp(45px,9vw,76px);color:var(--pink)">FLATLINED.</h2><p class="screen-lede">THE CITY REMEMBERS YOUR NAME. FOR A WHILE.</p><div class="stats-grid"><div class="stat-card"><b>${score.toLocaleString()}</b><span>FINAL SCORE</span></div><div class="stat-card"><b>${wave}</b><span>WAVE REACHED</span></div><div class="stat-card"><b>${kills}</b><span>TAKEDOWNS</span></div></div><div class="menu-actions"><button class="btn" id="retry">↻ &nbsp; RUN IT BACK</button><button class="btn secondary" id="records">RECORDS</button><button class="btn secondary" id="home">MAIN MENU</button></div>`);$('#retry').onclick=startGame;$('#home').onclick=menu;$('#records').onclick=showStats;}
function pause(){if(state==='playing'){screenReturn='playing';state='paused';show(`<div class="eyebrow">COMBAT SUSPENDED</div><h2 class="screen-heading">TAKE A BREATHER.</h2><p class="screen-lede">Wave ${wave} • ${enemies.length+(boss?1:0)} hostiles remain</p><div class="menu-actions"><button class="btn" id="resume">▶ &nbsp; RESUME</button><button class="btn secondary" id="settings">SETTINGS</button><button class="btn danger" id="quit">ABANDON RUN</button></div>`);$('#resume').onclick=()=>{hide();state='playing'};$('#settings').onclick=()=>showSettings();$('#quit').onclick=menu}else if(state==='paused'){hide();state='playing'}}
function addParticles(x,y,color,n=8,power=80){for(let i=0;i<n;i++){let a=rand(0,Math.PI*2),v=rand(power*.25,power);particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:rand(.18,.55),max:.55,color,size:rand(1,3)})}}
function nearest(){let target=null,d=Infinity;for(const e of enemies){let q=Math.hypot(e.x-player.x,e.y-player.y);if(q<d){d=q;target=e}}if(boss){let q=Math.hypot(boss.x-player.x,boss.y-player.y);if(q<d)target=boss}return target}
function strike(){if(player.attackTimer>0||state!=='playing')return;player.attackTimer=player.fireRate;let t=nearest();if(!t)return;let d=Math.hypot(t.x-player.x,t.y-player.y);if(d>110)return;let dmg=player.damage*(Math.random()<player.crit?2:1);t.hp-=dmg;stats.damage+=dmg;stats.shots++;player.angle=Math.atan2(t.y-player.y,t.x-player.x);addParticles(t.x,t.y,player.crit&&dmg>player.damage?'#ffcf5a':'#4cf6e8',7,90);audio(dmg>player.damage*1.5?540:320,.06,'square');shake=Math.max(shake,2);if(t===boss){boss.hit=.12}else if(t.hp<=0){killEnemy(t)}if(player.arc&&stats.shots%4===0){let chain=enemies.filter(e=>e!==t&&Math.hypot(e.x-t.x,e.y-t.y)<120).slice(0,2);chain.forEach(e=>{e.hp-=player.damage*.55;addParticles(e.x,e.y,'#a5faff',7,110);if(e.hp<=0)killEnemy(e)})}}
function killEnemy(e){let i=enemies.indexOf(e);if(i<0)return;enemies.splice(i,1);kills++;player.kills++;let val=types[e.type].value||25;score+=val*10;credits+=val;if(player.vamp)player.hp=Math.min(player.maxHp,player.hp+2);addParticles(e.x,e.y,e.color,12,105);if(kills===1)toast('FIRST BLOOD // BOUNTY CLAIMED');if(player.overclock)abilityCd=Math.max(0,abilityCd-.25)}
function useAbility(){if(state!=='playing'||abilityCd>0)return;let ab=abilities[abilityIndex];abilityCd=ab.cool*(player.coolMult||1);stats.abilities++;audio(180,.2,'sawtooth',.04);if(ab.id==='sandevistan'){player.slowTime=4;toast('SANDEVISTAN // TIME DILATED');addParticles(player.x,player.y,'#55f9eb',24,170)}else if(ab.id==='smash'){shake=13;addParticles(player.x,player.y,'#ffb84c',36,200);for(const e of [...enemies])if(Math.hypot(e.x-player.x,e.y-player.y)<145){e.hp-=95;if(e.hp<=0)killEnemy(e)}if(boss&&Math.hypot(boss.x-player.x,boss.y-player.y)<160)boss.hp-=100}else if(ab.id==='emp'){for(const e of enemies){if(Math.hypot(e.x-player.x,e.y-player.y)<230){e.hp-=52;e.stun=1.8;addParticles(e.x,e.y,'#55f9eb',8,100);if(e.hp<=0)killEnemy(e)}}if(boss&&Math.hypot(boss.x-player.x,boss.y-player.y)<250){boss.hp-=75;boss.attack+=1}addParticles(player.x,player.y,'#55f9eb',38,220);shake=7;toast('EMP BURST // HOSTILES DISABLED')}else{player.berserk=5;player.invuln=Math.max(player.invuln,1);toast('BERSERK // NO MERCY');addParticles(player.x,player.y,'#ff3d78',26,180)}}

