+function damagePlayer(amount){if(player.invuln>0)return;if(player.shield>0){player.shield=0;player.invuln=.55;addParticles(player.x,player.y,'#4cf6e8',15,120);toast('AEGIS SHIELD // HIT ABSORBED');return}player.hp-=Math.max(1,amount-player.armor);player.invuln=.5;shake=7;addParticles(player.x,player.y,'#ff3d78',11,120);audio(95,.14,'sawtooth',.04);if(player.hp<=0){player.hp=0;gameOver()}}
+function update(dt){if(state!=='playing')return;gameTime+=dt;player.attackTimer=Math.max(0,player.attackTimer-dt);player.invuln=Math.max(0,player.invuln-dt);player.dashCd=Math.max(0,player.dashCd-dt);player.slowTime=Math.max(0,player.slowTime-dt);player.berserk=Math.max(0,player.berserk-dt);abilityCd=Math.max(0,abilityCd-dt);if(player.shield>0)player.shield=Math.max(0,player.shield-dt);
+let dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+touch.x,dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)+touch.y;let mag=Math.hypot(dx,dy);if(mag>1){dx/=mag;dy/=mag}let speed=player.speed*(player.berserk?1.12:1);if(player.dash>0&&keys.has('shift')&&player.dashCd<=0){player.dashCd=2.4;player.invuln=.22;speed=440;addParticles(player.x,player.y,'#4cf6e8',12,100);shake=3}player.x+=dx*speed*dt;player.y+=dy*speed*dt;if(dx||dy)player.angle=Math.atan2(dy,dx);if(keys.has(' ')||touch.attack)strike();if(keys.has('q')||touch.special){useAbility();touch.special=false}
