+for(const e of [...enemies]){if(e.stun>0){e.stun-=dt;continue}let tscale=timeScale;let dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy)||1,ux=dx/d,uy=dy/d;e.attack-=dt*tscale;e.angle=Math.atan2(dy,dx);if(e.ai==='snipe'){if(d>195){e.x+=ux*e.speed*dt*tscale;e.y+=uy*e.speed*dt*tscale}else if(d<145){e.x-=ux*e.speed*.65*dt*tscale;e.y-=uy*e.speed*.65*dt*tscale}if(e.attack<=0&&d<430){enemyShots.push({x:e.x,y:e.y,vx:ux*185,vy:uy*185,damage:e.damage,r:3,color:e.color});e.attack=2.2;addParticles(e.x,e.y,e.color,4,50)}}else if(e.ai==='flank'){let side=Math.sin(gameTime*.8+e.phase);e.x+=(ux*.7-uy*side*.62)*e.speed*dt*tscale;e.y+=(uy*.7+ux*side*.62)*e.speed*dt*tscale;if(e.attack<=0&&d<185){enemyShots.push({x:e.x,y:e.y,vx:ux*125,vy:uy*125,damage:e.damage,r:3,color:e.color});e.attack=2.7}}else if(e.ai==='dash'){if(e.attack<=0&&d<210){e.speed*=2.6;e.attack=.35;e.phase=1}else{e.x+=ux*e.speed*dt*tscale;e.y+=uy*e.speed*dt*tscale;if(e.phase){e.phase=0;e.speed/=2.6}}}else{e.x+=ux*e.speed*dt*tscale;e.y+=uy*e.speed*dt*tscale;if(e.ai==='smart'&&e.attack<=0&&d<280){for(let a=-.2;a<=.2;a+=.2)enemyShots.push({x:e.x,y:e.y,vx:Math.cos(e.angle+a)*155,vy:Math.sin(e.angle+a)*155,damage:e.damage*.65,r:3,color:e.color});e.attack=2.1}}if(d<e.r+player.r+1&&player.invuln<=0)damagePlayer(e.damage*(player.berserk?.45:1))}
+for(const b of enemyShots){b.x+=b.vx*dt*timeScale;b.y+=b.vy*dt*timeScale;if(Math.hypot(b.x-player.x,b.y-player.y)<b.r+player.r){damagePlayer(b.damage);b.dead=true}}enemyShots=enemyShots.filter(b=>!b.dead&&Math.abs(b.x-player.x)<W&&Math.abs(b.y-player.y)<H);
