function worldToScreen(x,y){return [W/2+x-player.x,H/2+y-player.y]}
function rect(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}
function drawBackground(){ctx.fillStyle='#080b12';ctx.fillRect(0,0,W,H);const [cx,cy]=worldToScreen(0,0);let tile=64,ox=((cx%tile)+tile)%tile,oy=((cy%tile)+tile)%tile;for(let x=ox-tile;x<W+tile;x+=tile)for(let y=oy-tile;y<H+tile;y+=tile){let gx=Math.floor((x-cx)/tile),gy=Math.floor((y-cy)/tile),n=Math.abs((gx*37+gy*19)%11);rect(x,y,tile-2,tile-2,n<3?'#0c111a':'#0a0e16');if(n===1){rect(x+7,y+8,18,2,'#113038');rect(x+39,y+27,8,2,'#3b1430');rect(x+12,y+43,2,7,'#194351')}if(n===5){rect(x+tile/2,y+5,1,tile-12,'#101d27')}}
// dashed street lanes
ctx.strokeStyle='#18202a';ctx.lineWidth=1;ctx.setLineDash([12,14]);ctx.beginPath();ctx.moveTo(0,cy%160);ctx.lineTo(W,cy%160);ctx.stroke();ctx.beginPath();ctx.moveTo(cx%160,0);ctx.lineTo(cx%160,H);ctx.stroke();ctx.setLineDash([]);
// neon sign glows / rain
for(let i=0;i<24;i++){let x=(i*173+gameTime*22)%W,y=(i*97+gameTime*90)%H;ctx.globalAlpha=.22;rect(x,y,1,rand(3,10),'#72e9ed');ctx.globalAlpha=1}let grd=ctx.createRadialGradient(W/2,H/2,Math.min(W,H)*.1,W/2,H/2,Math.max(W,H)*.78);grd.addColorStop(0,'transparent');grd.addColorStop(1,'#02040ac9');ctx.fillStyle=grd;ctx.fillRect(0,0,W,H)}
function drawPerson(x,y,color,isPlayer=false,angle=0,r=8,health=1){let [sx,sy]=worldToScreen(x,y);if(sx<-40||sx>W+40||sy<-40||sy>H+40)return;ctx.save();ctx.translate(Math.round(sx),Math.round(sy));ctx.shadowBlur=isPlayer?18:12;ctx.shadowColor=color;ctx.fillStyle='#090d14';ctx.fillRect(-r,-r+1,r*2,r*2);ctx.shadowBlur=0;ctx.fillStyle=isPlayer?'#d7e8e5':'#adb8c7';ctx.fillRect(-r*.57,-r*.55,r*1.14,r*.92);ctx.fillStyle=color;ctx.fillRect(-r*.7,-r*.7,r*1.4,r*.35);ctx.fillStyle=isPlayer?'#101b25':'#202736';ctx.fillRect(-r*.48,r*.36,r*.96,r*.75);ctx.fillStyle=color;ctx.fillRect(-r*.57,r*.85,r*.42,r*.42);ctx.fillRect(r*.15,r*.85,r*.42,r*.42);ctx.rotate(angle);ctx.fillStyle=isPlayer?'#4cf6e8':color;ctx.fillRect(r*.35,-2,r*1.15,3);ctx.fillStyle='#f6ffff';ctx.fillRect(r*.15,-2,2,2);ctx.restore();if(health<1){rect(sx-r,sy-r-7,r*2,2,'#222b35');rect(sx-r,sy-r-7,r*2*health,2,color)}}
function draw(){ctx.save();let sh=shake?rand(-shake,shake):0;ctx.translate(sh,shake?rand(-shake,shake):0);drawBackground();for(const b of enemyShots){let [x,y]=worldToScreen(b.x,b.y);ctx.shadowBlur=10;ctx.shadowColor=b.color;rect(x-2,y-2,4,4,b.color);ctx.shadowBlur=0}for(const p of particles){let [x,y]=worldToScreen(p.x,p.y);ctx.globalAlpha=clamp(p.life/p.max,0,1);rect(x-p.size/2,y-p.size/2,p.size,p.size,p.color)}ctx.globalAlpha=1;for(const e of enemies)drawPerson(e.x,e.y,e.color,false,e.angle,e.r,e.hp/e.maxHp);if(boss){let [x,y]=worldToScreen(boss.x,boss.y);ctx.shadowBlur=25;ctx.shadowColor='#ff315d';ctx.fillStyle='#260c1c';ctx.fillRect(x-25,y-23,50,48);ctx.shadowBlur=0;ctx.fillStyle=boss.hit?'#fff':'#c42b55';ctx.fillRect(x-20,y-19,40,37);ctx.fillStyle='#161725';ctx.fillRect(x-13,y-12,26,23);ctx.fillStyle='#fff06b';ctx.fillRect(x-13,y-6,9,3);ctx.fillRect(x+4,y-6,9,3);ctx.fillStyle='#ff3e73';ctx.fillRect(x-20,y+13,40,5);ctx.fillStyle='#ffe2a6';ctx.fillRect(x-3,y+1,7,3);ctx.fillStyle='#210d19';ctx.fillRect(W/2-85,44,170,7);ctx.fillStyle='#ff3d78';ctx.fillRect(W/2-84,45,168*clamp(boss.hp/boss.maxHp,0,1),5);ctx.fillStyle='#ffe1e7';ctx.font='9px monospace';ctx.textAlign='center';ctx.fillText(`${boss.name} // PHASE ${boss.phase}`,W/2,39)}
let [px,py]=worldToScreen(player.x,player.y);if(player.slowTime>0){ctx.strokeStyle='#4cf6e866';ctx.lineWidth=2;ctx.beginPath();ctx.arc(px,py,28+Math.sin(gameTime*9)*3,0,Math.PI*2);ctx.stroke()}if(player.shield>0){ctx.strokeStyle='#4cf6e8';ctx.lineWidth=2;ctx.beginPath();ctx.arc(px,py,15,0,Math.PI*2);ctx.stroke()}if(player.invuln<=0||Math.floor(gameTime*20)%2===0)drawPerson(player.x,player.y,player.berserk?'#ff3d78':'#4cf6e8',true,player.angle,player.r,1);if(player.berserk){ctx.globalAlpha=.35;ctx.strokeStyle='#ff3d78';ctx.beginPath();ctx.arc(px,py,19,0,6.28);ctx.stroke();ctx.globalAlpha=1}
// ability card
if(state==='playing'){let bx=W-112,by=H-24;rect(bx,by-9,88,7,'#17222e');rect(bx,by-9,88*(1-abilityCd/(abilities[abilityIndex].cool*(player.coolMult||1))),7,abilityCd>0?'#687586':'#4cf6e8');ctx.fillStyle=abilityCd>0?'#aab5c2':'#4cf6e8';ctx.font='8px monospace';ctx.textAlign='right';ctx.fillText(`${abilities[abilityIndex].name} ${abilityCd>0?Math.ceil(abilityCd)+'s':'READY'}`,W-18,by-13)}ctx.restore()}
function frame(t){let dt=Math.min(.033,(t-last)/1000||0);last=t;if(state==='playing')update(dt);draw();requestAnimationFrame(frame)}requestAnimationFrame(frame);

