 function showSettings(){state='menu';show(`<div class="eyebrow">SYSTEM CONFIGURATION</div><h2 class="screen-heading">SETTINGS</h2><p class="screen-lede">Tune the signal. Settings are saved for this session.</p><div class="settings-row"><span>Synthwave soundtrack</span><button class="toggle" id="music">${musicOn?'ON':'OFF'}</button></div><div class="settings-row"><span>Combat sound effects</span><button class="toggle" id="sfx">${sfxOn?'ON':'OFF'}</button></div><div class="settings-row"><span>Control scheme</span><span style="color:var(--cyan);font:10px 'Share Tech Mono'">KEYBOARD + TOUCH</span></div><div class="menu-actions"><button class="btn secondary" id="back">← BACK</button><button class="btn danger" id="reset">RESET RECORDS</button></div>`);$('#music').onclick=e=>{musicOn=!musicOn;e.target.textContent=musicOn?'ON':'OFF'};$('#sfx').onclick=e=>{sfxOn=!sfxOn;e.target.textContent=sfxOn?'ON':'OFF'};$('#back').onclick=menu;$('#reset').onclick=()=>{if(confirm('Erase all local records?')){Object.assign(meta,{high:0,bestWave:0,totalKills:0,runs:0,unlocks:[]});persist();menu()}};}
